export function parseMaybeJson(value, fallback) {
    if (typeof value !== 'string') {
        return (value ?? fallback);
    }
    const trimmed = value.trim();
    if (!trimmed)
        return fallback;
    try {
        return JSON.parse(trimmed);
    }
    catch {
        return fallback;
    }
}
export function parseOrderBranch(value) {
    if (!value)
        return undefined;
    return typeof value === 'string'
        ? parseMaybeJson(value, undefined)
        : value;
}
export function getBranchPhone(contacts) {
    const parsed = parseMaybeJson(contacts, null);
    const phone = parsed && typeof parsed === 'object' ? parsed.phone : '';
    return typeof phone === 'string' ? phone.trim() : '';
}
export function formatTimeTo12h(time24, locale = 'ar') {
    const [hours, minutes] = String(time24).trim().split(':').map(Number);
    if (!Number.isFinite(hours) || !Number.isFinite(minutes))
        return time24;
    const date = new Date(2000, 0, 1, hours, minutes);
    const options = { hour: 'numeric', minute: '2-digit', hour12: true };
    try {
        return date.toLocaleTimeString(locale, options);
    }
    catch {
        return date.toLocaleTimeString('ar', options);
    }
}
export function normalizeTimeUnit(unit) {
    const normalized = String(unit || 'hour').toLowerCase();
    if (normalized.startsWith('min'))
        return 'minute';
    if (normalized.startsWith('day'))
        return 'day';
    return 'hour';
}
